const CACHE_NAME="hive-v117",HTML_FALLBACK="/index.html",ASSETS=["/manifest.json","/api.js"];self.addEventListener("install",e=>{e.waitUntil((async()=>{const cache=await caches.open(CACHE_NAME);await cache.addAll(ASSETS);try{const html=await fetch(HTML_FALLBACK,{cache:"no-store"});html.ok&&await cache.put(HTML_FALLBACK,html.clone())}catch{}})()),self.skipWaiting()}),self.addEventListener("activate",e=>{e.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(k=>k!==CACHE_NAME).map(k=>caches.delete(k))),await self.clients.claim()})())}),self.addEventListener("fetch",e=>{if(e.request.method!=="GET"||e.request.url.includes("/api/"))return;const url=new URL(e.request.url);if(url.origin!==self.location.origin)return;if(url.pathname==="/"||url.pathname.endsWith(".html")||e.request.mode==="navigate"){e.respondWith((async()=>{try{const fresh=await fetch(e.request);return fresh.ok&&(await caches.open(CACHE_NAME)).put(HTML_FALLBACK,fresh.clone()).catch(()=>{}),fresh}catch{const cached=await caches.match(HTML_FALLBACK);return cached||new Response('<!doctype html><meta charset=utf-8><title>Hivex</title><body style="font-family:system-ui;padding:40px;text-align:center;background:#0f172a;color:#e2e8f0"><h1>Sem liga\xE7\xE3o</h1><p>Verifique a sua liga\xE7\xE3o \xE0 internet e tente novamente.</p><button onclick="location.reload()" style="margin-top:16px;padding:10px 20px;background:#f97316;color:#fff;border:0;border-radius:8px;font-weight:700;cursor:pointer">Tentar de novo</button></body>',{headers:{"Content-Type":"text/html; charset=utf-8"}})}})());return}e.respondWith(fetch(e.request).then(response=>{if(response.ok){const clone=response.clone();caches.open(CACHE_NAME).then(cache=>cache.put(e.request,clone))}return response}).catch(()=>caches.match(e.request)))});
